<?php
require_once '../../config/auth.php';
require_once '../../config/database.php';
requireLogin();
if (($_SESSION['role'] ?? '') !== 'admin') { header('Location: ../../index.php'); exit; }

$pengurus = $pdo->query("SELECT co.id, co.student_id, co.class_id, co.position, co.academic_year_id, co.tanggal_mulai, co.tanggal_selesai, co.status, s.nama_lengkap, c.nama_kelas, c.tingkat, c.jurusan, COALESCE(NULLIF(d.singkatan, ''), c.jurusan, '') AS jurusan_singkat, ay.tahun_ajaran FROM class_officers co INNER JOIN students s ON s.id = co.student_id INNER JOIN classes c ON c.id = co.class_id INNER JOIN academic_years ay ON ay.id = co.academic_year_id LEFT JOIN departments d ON d.nama_jurusan = c.jurusan ORDER BY co.status DESC, c.nama_kelas ASC, co.position ASC, s.nama_lengkap ASC")->fetchAll(PDO::FETCH_ASSOC);
$totalPengurus = count($pengurus);
$bendaharaAktif = count(array_filter($pengurus, static fn($row) => $row['position'] === 'bendahara_kelas' && $row['status'] === 'aktif'));
$menungguVerifikasi = count(array_filter($pengurus, static fn($row) => $row['status'] === 'menunggu'));
$totalKelas = count(array_unique(array_column($pengurus, 'class_id')));
$pageTitle = 'Bendahara Kelas';
require_once '../../includes/header.php';
require_once '../../includes/sidebar.php';
?>
<main class="main-content">
    <?php require_once '../../includes/navbar.php'; ?>
    <section class="dashboard-container officer-page-modern">
        <section class="officer-page-hero"><div><span class="officer-page-kicker"><i class="bi bi-person-workspace"></i> Administrasi Kelas</span><h2>Bendahara Kelas</h2><p>Pantau penugasan Bendahara Kelas, status verifikasi, dan periode kepengurusan setiap kelas.</p></div><div class="officer-hero-icon"><i class="bi bi-wallet2"></i></div></section>

        <section class="officer-stat-grid"><article><span class="officer-stat-icon blue"><i class="bi bi-person-workspace"></i></span><div><small>Total pengurus</small><strong><?= $totalPengurus ?></strong><p>Data kepengurusan kelas</p></div></article><article><span class="officer-stat-icon teal"><i class="bi bi-wallet2"></i></span><div><small>Bendahara aktif</small><strong><?= $bendaharaAktif ?></strong><p>Sedang bertugas</p></div></article><article><span class="officer-stat-icon amber"><i class="bi bi-clock-history"></i></span><div><small>Menunggu verifikasi</small><strong><?= $menungguVerifikasi ?></strong><p>Perlu ditinjau Admin</p></div></article><article><span class="officer-stat-icon violet"><i class="bi bi-door-open"></i></span><div><small>Kelas tertaut</small><strong><?= $totalKelas ?></strong><p>Kelas memiliki pengurus</p></div></article></section>

        <?php if (isset($_GET['success'])): ?><div class="alert alert-success officer-alert"><i class="bi bi-check-circle-fill"></i><?= $_GET['success'] === 'tambah' ? 'Pengurus kelas berhasil ditambahkan.' : ($_GET['success'] === 'edit' ? 'Data pengurus kelas berhasil diperbarui.' : 'Data pengurus kelas berhasil diarsipkan.') ?></div><?php endif; ?>
