        <section class="officer-list-card"><div class="officer-list-head"><div><span class="eyebrow">Daftar penugasan</span><h4>Bendahara dan pengurus kelas</h4><p>Kelola status kepengurusan dari daftar berikut.</p></div><div class="officer-search"><i class="bi bi-search"></i><input type="search" id="officerSearch" placeholder="Cari nama, kelas, atau jurusan..."></div></div><div class="table-responsive"><table class="table officer-modern-table align-middle mb-0"><thead><tr><th>No.</th><th>Pengurus</th><th>Kelas</th><th>Jabatan</th><th>Tahun ajaran</th><th>Periode</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody id="officerTableBody">
            <?php foreach ($pengurus as $index => $row): $isTreasurer = $row['position'] === 'bendahara_kelas'; ?><tr data-search="<?= htmlspecialchars(strtolower($row['nama_lengkap'] . ' ' . $row['nama_kelas'] . ' ' . $row['jurusan_singkat'])) ?>"><td class="officer-row-number"><?= $index + 1 ?></td><td><div class="officer-profile-cell"><span class="officer-avatar"><?= htmlspecialchars(strtoupper(substr($row['nama_lengkap'], 0, 1))) ?></span><strong><?= htmlspecialchars($row['nama_lengkap']) ?></strong></div></td><td><strong><?= htmlspecialchars($row['nama_kelas']) ?></strong><?php if ($row['jurusan_singkat'] !== ''): ?><small class="d-block officer-department"><i class="bi bi-building"></i> <?= htmlspecialchars($row['jurusan_singkat']) ?></small><?php endif; ?></td><td><span class="officer-position <?= $isTreasurer ? 'treasurer' : 'leader' ?>"><i class="bi <?= $isTreasurer ? 'bi-wallet2' : 'bi-person-badge' ?>"></i><?= $isTreasurer ? 'Bendahara Kelas' : 'Ketua Kelas' ?></span></td><td><?= htmlspecialchars($row['tahun_ajaran']) ?></td><td><span class="officer-period"><strong><?= date('d M Y', strtotime($row['tanggal_mulai'])) ?></strong><small>s/d <?= $row['tanggal_selesai'] ? date('d M Y', strtotime($row['tanggal_selesai'])) : 'Sekarang' ?></small></span></td><td><span class="officer-status <?= htmlspecialchars($row['status']) ?>"><i class="bi bi-circle-fill"></i><?= $row['status'] === 'menunggu' ? 'Menunggu' : htmlspecialchars(ucfirst($row['status'])) ?></span></td><td class="text-end"><div class="officer-action-group"><?php if ($row['position'] === 'ketua_kelas' && $row['status'] === 'menunggu'): ?><form method="post" action="verifikasi_ketua.php" class="d-inline"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><button type="submit" name="action" value="setujui" class="btn btn-sm btn-success" title="Setujui ketua kelas"><i class="bi bi-check-lg"></i></button><button type="submit" name="action" value="tolak" class="btn btn-sm btn-light text-danger" title="Tolak ketua kelas"><i class="bi bi-x-lg"></i></button></form><?php endif; ?><a href="edit.php?id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-light text-primary" title="Edit pengurus"><i class="bi bi-pencil-square"></i></a><a href="hapus.php?id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-light text-danger" title="Hapus pengurus" onclick="return confirm('Yakin ingin menghapus data pengurus ini?');"><i class="bi bi-trash"></i></a></div></td></tr><?php endforeach; ?>
            <?php if (!$pengurus): ?><tr><td colspan="8" class="text-center text-muted py-5"><i class="bi bi-person-workspace d-block fs-2 mb-2"></i>Belum ada data pengurus kelas.</td></tr><?php endif; ?><tr id="officerNotFound" class="d-none"><td colspan="8" class="text-center text-muted py-5"><i class="bi bi-search d-block fs-3 mb-2"></i>Pengurus tidak ditemukan.</td></tr>
        </tbody></table></div></section>
    </section>
</main>
<script>document.getElementById('officerSearch')?.addEventListener('input', function () { const keyword = this.value.trim().toLowerCase(); const rows = Array.from(document.querySelectorAll('#officerTableBody tr[data-search]')); let found = 0; rows.forEach(row => { const visible = row.dataset.search.includes(keyword); row.classList.toggle('d-none', !visible); if (visible) found++; }); document.getElementById('officerNotFound')?.classList.toggle('d-none', found !== 0 || keyword === ''); });</script>
